CREATE EXTENSION IF NOT EXISTS vector;
CREATE TYPE "PublishStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "RouteType" AS ENUM ('PAGE','REDIRECT');
CREATE TYPE "ContentType" AS ENUM ('ARTICLE','VIDEO','FAQ');
CREATE TYPE "UserRole" AS ENUM ('USER','EDITOR','ADMIN','SUPER_ADMIN');
CREATE TABLE "User"("id" TEXT PRIMARY KEY,"email" TEXT UNIQUE,"displayName" TEXT,"passwordHash" TEXT,"role" "UserRole" NOT NULL DEFAULT 'USER',"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Page"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"routeType" "RouteType" NOT NULL DEFAULT 'PAGE',"redirectUrl" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"layout" JSONB NOT NULL DEFAULT '[]',"draftLayout" JSONB NOT NULL DEFAULT '[]',"seoTitle" TEXT,"seoDescription" TEXT,"seoKeywords" TEXT,"ogImage" TEXT,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Category"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"parentId" TEXT,"sort" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "Category_parentId_fkey" FOREIGN KEY("parentId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Content"("id" TEXT PRIMARY KEY,"type" "ContentType" NOT NULL DEFAULT 'ARTICLE',"title" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"summary" TEXT,"body" TEXT NOT NULL,"coverUrl" TEXT,"videoUrl" TEXT,"categoryId" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"ragEnabled" BOOLEAN NOT NULL DEFAULT true,"viewCount" INTEGER NOT NULL DEFAULT 0,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Content_categoryId_fkey" FOREIGN KEY("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "KnowledgeChunk"("id" TEXT PRIMARY KEY,"contentId" TEXT NOT NULL,"text" TEXT NOT NULL,"embedding" vector(1536),"tokenCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "KnowledgeChunk_contentId_fkey" FOREIGN KEY("contentId") REFERENCES "Content"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "KnowledgeChunk_embedding_idx" ON "KnowledgeChunk" USING hnsw ("embedding" vector_cosine_ops);
CREATE TABLE "Product"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"summary" TEXT,"description" TEXT NOT NULL,"price" DECIMAL(12,2) NOT NULL,"compareAtPrice" DECIMAL(12,2),"stock" INTEGER NOT NULL DEFAULT 0,"sales" INTEGER NOT NULL DEFAULT 0,"coverUrl" TEXT,"gallery" JSONB NOT NULL DEFAULT '[]',"externalUrl" TEXT NOT NULL,"categoryId" TEXT,"status" "PublishStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY("categoryId") REFERENCES "Category"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "Theme"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"variables" JSONB NOT NULL,"effects" JSONB NOT NULL DEFAULT '{}',"active" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ThemeSchedule"("id" TEXT PRIMARY KEY,"themeId" TEXT NOT NULL,"startAt" TIMESTAMP(3) NOT NULL,"endAt" TIMESTAMP(3) NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "ThemeSchedule_themeId_fkey" FOREIGN KEY("themeId") REFERENCES "Theme"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "MarketingCampaign"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"kind" TEXT NOT NULL,"config" JSONB NOT NULL,"startAt" TIMESTAMP(3),"endAt" TIMESTAMP(3),"enabled" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "GlobalSetting"("key" TEXT PRIMARY KEY,"value" JSONB NOT NULL,"public" BOOLEAN NOT NULL DEFAULT false,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PluginSnippet"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"position" TEXT NOT NULL,"code" TEXT NOT NULL,"delayMs" INTEGER NOT NULL DEFAULT 3000 CHECK ("delayMs">=3000),"enabled" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AuditLog"("id" TEXT PRIMARY KEY,"userId" TEXT,"action" TEXT NOT NULL,"resource" TEXT NOT NULL,"resourceId" TEXT,"detail" JSONB,"ip" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
